const body = $json;
const execs = Array.isArray(body.data) ? body.data : [];
const out = [];
for (const e of execs) {
  const rd = (e.data && e.data.resultData && e.data.resultData.runData) || {};
  const cm = rd['Chat Model'];
  if (!cm) continue;
  let pt=0, ct=0, modelo='desconocido';
  for (const run of cm) {
    try {
      const j = run.data.ai_languageModel[0][0].json;
      const tu = j.tokenUsage || {};
      pt += tu.promptTokens||0; ct += tu.completionTokens||0;
      modelo = (j.response.generations[0][0].generationInfo.model_name) || modelo;
    } catch(err){}
  }
  let conv=null, etapa=null;
  try { conv = rd['Cargar estado'][0].data.main[0][0].json.id; } catch(err){}
  try { etapa = rd['Cargar etapa activa'][0].data.main[0][0].json.id; } catch(err){}
  if (!conv || (pt===0 && ct===0)) continue;
  out.push({ json: { execution_id: String(e.id), creado_en: String(e.startedAt || e.stoppedAt || ''), conversacion_id: conv, etapa_id: etapa || '', modelo, prompt_tokens: pt, completion_tokens: ct } });
}
return out;
